static boolean[] primeSieve(int limit) {

    boolean[] primes = new boolean[limit + 1];

    for (int number = 2; number < limit; number++) {
        primes[number] = true;
    }

    for (int currentPrime = 2; currentPrime < limit; currentPrime = nextPrime(primes, currentPrime)) {

        for (int multiple = currentPrime + 1; multiple < limit; multiple += currentPrime) {

