    this.sqrt_one_minus_alphas_cumprod = this.one_minus_alphas_cumprod.sqrt();
    this.sqrt_recip_alphas_cumprod = this.alphas_cumprod.sqrt().reciprocal();
    this.sqrt_recipm1_alphas_cumprod = tf.sub(this.alphas_cumprod.sqrt(), 1).reciprocal();
  }

