def is_valid(board, row, col, num):
    # Check if the number is not already present in the current row
    for x in range(9):
        if board[row][x] == num:
            return False

    # Check if the number is not already present in the current column
    for x in range(9):
        if board[x][col] == num:
            return False

    # Check if the number is not already present in the 3x3 sub-grid
    start_row = row - row % 3
    start_col = col - col % 3
    for i in range(3):
        for j in range(3):
            if board[i + start_row][j + start_col] == num:
                return False

    return True

def solve_sudoku(board):
